"""The dashboard page: the collected numbers turned into one self-contained HTML string.

`render` builds the page shell (top bar, repository select, footer) around one `cards.section` per view. The styles and
the script live in page.css and page.js next to this file; `render` reads them and inlines them, with the body font
and the orq mark from assets/, so the page loads nothing from the network. Never reads a store, never computes numbers.
"""

from __future__ import annotations

import base64
import json
from pathlib import Path
from typing import TYPE_CHECKING

from . import attention, cards, parts, text

if TYPE_CHECKING:
    from .data import Page, StoreView

__all__ = ['FONTS', 'render']


PLUGIN_DIR = Path(__file__).resolve().parents[3]  # src/memorq/dashboard/render.py -> the plugin folder


def _page_file(name: str) -> str:
    """page.css or page.js, next to this file; the page inlines them, so it stays self-contained."""
    return Path(__file__).with_name(name).read_text(encoding='utf-8')


def _asset(path: Path) -> str:
    try:
        return path.read_text()
    except OSError:
        return ''


FONTS: tuple[tuple[str, int], ...] = (('AvioSans-Regular', 400), ('AvioSans-Medium', 500), ('AvioSans-SemiBold', 600))
"""The product's body face, three weights, subset by `npm run fonts` (vendored from orquesta-web via evaluatorq)."""


def _font_face() -> str:
    """One @font-face per weight of Avio Sans, embedded so the page stays self-contained; a missing file is skipped."""
    faces = []
    for name, weight in FONTS:
        try:
            data = base64.b64encode((PLUGIN_DIR / 'assets' / f'{name}.woff2').read_bytes()).decode()
        except OSError:
            continue
        faces.append(
            f"@font-face{{font-family:'Avio Sans';src:url(data:font/woff2;base64,{data}) format('woff2');"
            f'font-weight:{weight};font-display:swap}}'
        )
    return '\n'.join(faces)


def _version() -> str:
    try:
        return json.loads((PLUGIN_DIR / '.claude-plugin' / 'plugin.json').read_text())['version']
    except (OSError, ValueError, KeyError):
        return ''


def _repo_select(stores: list[StoreView]) -> str:
    """One select in the top bar, so the repository can be changed from anywhere on the page."""
    groups: dict[str, list[str]] = {}
    for st in stores:
        owner, _, repo = st['key'].partition('__')
        groups.setdefault(owner if repo else '', []).append(
            f'<option value="{parts.esc(st["key"])}">{parts.esc(repo or st["key"])} · {text.plural(len(st["notes"]), "note")}</option>'
        )
    total = sum(len(st['notes']) for st in stores)
    options = [f'<option value="all">All repositories · {text.plural(total, "note")}</option>'] + [
        f'<optgroup label="{parts.esc(owner)}">{"".join(opts)}</optgroup>' if owner else ''.join(opts)
        for owner, opts in groups.items()
    ]
    return f'<label class="repo-pick"><span>Repository</span><select id="repo">{"".join(options)}</select></label>'


def render(data: Page) -> str:
    """The whole page for what `collect.collect` returned: one HTML string, CSS, script, font and logo inlined."""
    stores = data['stores']
    if not stores:
        body = parts.empty(
            'No knowledge notes yet.', 'Do some work in a git repository, end the session, and come back.'
        )
        picker = ''
    else:
        picker = _repo_select(stores)
        problems = {s['key']: attention.problems(s) for s in stores}
        body = cards.overview(data['all'], stores, problems) + ''.join(
            cards.section(s, s['key'], with_store_column=False, problems=problems[s['key']]) for s in stores
        )
    failed = ''.join(f' · could not read: {parts.esc(k)} ({parts.esc(err)})' for k, err in data.get('errors', []))
    mark, version = _asset(PLUGIN_DIR / 'assets' / 'orq-mark.svg'), _version()
    last = parts.esc(parts.stamp(max((s['last_update'] for s in stores), default='')))
    return f"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>memorq · orq memory notes dashboard</title><style>{_font_face()}\n{_page_file('page.css')}</style></head>
<body>
<header class="topbar"><a class="brand" href="#all"><span class="mark">{mark}</span><span class="brand-name">memor<span class="accent">q</span></span></a>
<h1 class="app-title">orq memory notes dashboard</h1>
{picker}
<span class="app-meta" title="Newest session or dream in any store; the page was built {parts.esc(parts.stamp(data['generated']))}">last update {last} · {len(stores)} repositories{failed}</span></header>
<div class="wrap">
<main>{body}</main><noscript><style>section{{display:block}}</style></noscript>
<footer class="foot"><span class="mark">{mark}</span>Generated by memorq{' ' + parts.esc(version) if version else ''}, from {parts.esc(data.get('root', ''))} · built {parts.esc(parts.stamp(data['generated']))} · no model calls, nothing leaves this machine</footer>
</div><script>\n{_page_file('page.js')}</script></body></html>
"""
